def f(x, y):
    S = x + y
    # f(x, y) = S*(S+1)/2 + x
    # S*(S+1) is always even, so division by 2 is exact.
    triangular_number = S * (S + 1) // 2
    return triangular_number + x

N = 0
limit = 100
for x in range(limit):
    for y in range(limit):
        if f(x, y) % 2 != 0:
            N += 1

print(N)
